const CACHE_NAME="gys-cache-v83",APP_VERSION="3.8.29";self.addEventListener("install",t=>{self.skipWaiting()}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(s=>Promise.all(s.map(r=>{if(r!==CACHE_NAME)return caches.delete(r)}))).then(()=>self.clients.claim()).then(()=>self.clients.matchAll({includeUncontrolled:!0}).then(s=>{s.forEach(r=>{try{r.postMessage({type:"SW_ACTIVATED",version:APP_VERSION})}catch{}})})))}),self.addEventListener("message",t=>{if(t.data&&t.data.type==="GET_VERSION"){if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"VERSION",version:APP_VERSION})}catch{}if(t.source)try{t.source.postMessage({type:"VERSION",version:APP_VERSION})}catch{}}t.data&&t.data.type==="CLEAR_CACHE"&&caches.keys().then(s=>Promise.all(s.map(r=>caches.delete(r)))).then(()=>{if(t.ports&&t.ports[0])try{t.ports[0].postMessage({type:"CACHE_CLEARED"})}catch{}if(t.source)try{t.source.postMessage({type:"CACHE_CLEARED"})}catch{}})}),self.addEventListener("fetch",t=>{if(t.request.method==="GET"){var s;try{s=new URL(t.request.url)}catch{return}if(s.pathname.includes("/midi/")||s.pathname.includes("/pdf/")||s.pathname.includes("/chord/")||s.pathname.includes("assets-list.json")||s.pathname.includes("assets-lyrics.json")||s.pathname.includes("assets-chord-list.json")||s.pathname.endsWith(".sf2")||s.pathname.endsWith(".sf3")){t.respondWith(fetch(t.request));return}var r=s.origin===self.location.origin&&(s.pathname.endsWith(".js")||s.pathname.endsWith(".css")||s.pathname.endsWith(".html")||s.pathname==="/"||s.pathname.endsWith("/"));if(r){if(/[?&]v=/.test(s.search)){t.respondWith(caches.open(CACHE_NAME).then(a=>a.match(t.request).then(e=>{var c=fetch(t.request).then(h=>(h&&h.status===200&&a.put(t.request,h.clone()),h)).catch(()=>null);return e||c.then(h=>h||Response.error())})));return}t.respondWith(caches.open(CACHE_NAME).then(a=>fetch(t.request).then(e=>(e&&e.status===200&&a.put(t.request,e.clone()),e)).catch(()=>caches.match(t.request).then(e=>e||Response.error()))));return}t.respondWith(caches.match(t.request).then(a=>a||fetch(t.request).then(e=>{if(e&&(e.status===200||e.type==="opaque")){var c=e.clone();caches.open(CACHE_NAME).then(h=>{h.put(t.request,c)})}return e}).catch(()=>Response.error())))}});
